python3 -c "
import json
a=json.load(open('candidate-import.json')); b=json.load(open('eval-log/run-dev-graph-system-spec/R3-import/import-payload.json'))
def walk(x,y,p=''):
  if type(x)!=type(y): print('TYPE',p,repr(x)[:300],'=>',repr(y)[:300]); return
  if isinstance(x,dict):
    for k in sorted(set(x)|set(y)):
      if k not in x: print('ADD',p+'/'+k, json.dumps(y[k],ensure_ascii=False)[:400])
      elif k not in y: print('DEL',p+'/'+k, json.dumps(x[k],ensure_ascii=False)[:400])
      else: walk(x[k],y[k],p+'/'+k)
  elif isinstance(x,list):
    if len(x)!=len(y): print('LEN',p,len(x),len(y))
    for i,(u,v) in enumerate(zip(x,y)): walk(u,v,p+f'[{i}]')
  elif x!=y: print('CHG',p,'\n   OLD:',repr(x)[:600],'\n   NEW:',repr(y)[:600])
walk(a,b)
"
